using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
public static class V5Tests {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static void Pump(Func<bool> done,int seconds=20){var frame=new DispatcherFrame();var watch=Stopwatch.StartNew();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(15)};timer.Tick+=(s,e)=>{if(done()||watch.Elapsed.TotalSeconds>seconds){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);Check(done(),"UI async operation timed out");}
 static Metrics Sample(int index){var m=Program.Fixture("eight");m.Cpu=(index%101).ToString(CultureInfo.InvariantCulture)+"%";m.Processes[0].User="baiyang";m.Processes[1].User="alice";return m;}
 public static int Persistence(string directory,bool write){Directory.CreateDirectory(directory);var store=new ArchiveStore(Path.Combine(directory,"restart-store"));var server=Storage.DefaultServer();var time=new DateTime(2026,10,20,2,0,0,DateTimeKind.Utc);if(write){store.Append(server,ArchiveRecord.From(Sample(45),time,5));File.WriteAllText(Path.Combine(directory,"restart-write.txt"),"WRITTEN=True");}else{var data=store.Query(server,time.AddSeconds(-1),time.AddSeconds(1),CancellationToken.None);Check(data.Points.Count==1,"records persist across process exit");var m=store.Read(data.Points[0]).Metrics();Check(m.Cpu=="45%"&&m.Processes[0].User=="baiyang"&&m.CpuCores.Count==128,"restart full snapshot");File.WriteAllText(Path.Combine(directory,"restart-read.txt"),"CROSS_PROCESS_ARCHIVE_RECOVERY=True");}return 0;}
 public static int Run(string directory){directory=Path.GetFullPath(directory);Directory.CreateDirectory(directory);var log=new List<string>();var root=Path.Combine(directory,"store");var store=new ArchiveStore(root){Days=365};var server=Storage.DefaultServer();var other=server.Copy();other.User="another";var local=Storage.LocalServer();var now=DateTime.UtcNow;var from=now.AddMinutes(-30);var to=now.AddSeconds(5);
 for(int i=0;i<180;i++){var m=Sample(i);if(i==85)m.Error="connection unavailable";store.Append(server,ArchiveRecord.From(m,from.AddSeconds(i*10),5));}store.Append(other,ArchiveRecord.From(Sample(12),from.AddMinutes(1),5));store.Append(local,ArchiveRecord.From(Program.Fixture("none"),from.AddMinutes(1),5));var data=store.Query(server,from,to,CancellationToken.None);Check(data.Points.Count==180,"persistent query count");Check(store.Query(other,from,to,CancellationToken.None).Points.Count==1,"user isolation");Check(store.Query(local,from,to,CancellationToken.None).Points.Count==1,"local isolation");log.Add("DEVICE_ARCHIVE_ISOLATION=True");Check(data.Points[0].T==from.Ticks,"UTC boundary is inclusive");var exact=store.Query(server,from.AddSeconds(10),from.AddSeconds(20),CancellationToken.None);Check(exact.Points.Count==2,"inclusive time boundaries");Check(store.Query(server,from.ToLocalTime(),to.ToLocalTime(),CancellationToken.None).Points.Count==180,"local timezone conversion");log.Add("UTC_LOCAL_AND_EXACT_RANGE_BOUNDARIES=True");
 var snapshot=store.Read(data.Points[10]);Check(snapshot.Metrics().Processes[0].User=="baiyang"&&snapshot.Metrics().CpuCores.Count==128,"full process/core snapshot");Check(!ArchiveStore.Json().Serialize(snapshot).Contains("KeyPath"),"no SSH key path in snapshots");log.Add("FULL_GPU_PROCESS_USERNAME_AND_CORE_SNAPSHOTS=True");
 string corrupt=data.Points[data.Points.Count-1].File;File.AppendAllText(corrupt,"{partial crash");store.Append(server,ArchiveRecord.From(Sample(88),to.AddSeconds(-1),5));var recovered=store.Query(server,from,to,CancellationToken.None);Check(recovered.Points.Count==181&&recovered.Skipped==1,"recover truncated tail then append");log.Add("TRUNCATED_RECORD_RECOVERY=True");
 var token=new CancellationTokenSource();token.Cancel();bool cancelled=false;try{store.Query(server,from,to,token.Token);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"query cancellation");log.Add("QUERY_CANCELLATION=True");
 var gap=new ArchiveResult{From=from.Ticks,To=to.Ticks,Header=ArchiveHeader.From(server)};gap.Points.Add(new ArchivePoint{T=from.Ticks,Cpu=25,Interval=5});gap.Points.Add(new ArchivePoint{T=from.AddSeconds(5).Ticks,Cpu=50,Interval=5});gap.Points.Add(new ArchivePoint{T=from.AddSeconds(10).Ticks,Error="offline",Interval=5});gap.Points.Add(new ArchivePoint{T=from.AddSeconds(15).Ticks,Cpu=75,Interval=5});gap.Points.Add(new ArchivePoint{T=from.AddMinutes(3).Ticks,Cpu=30,Interval=5});Check(gap.Plot("CPU").Count(x=>x.Break)==3,"gaps not joined");var dense=new ArchiveResult{From=from.Ticks,To=from.AddSeconds(60).Ticks};for(int i=0;i<6000;i++)dense.Points.Add(new ArchivePoint{T=from.AddMilliseconds(i*10).Ticks,Cpu=i==1234?100:5,Interval=2});var plot=dense.Plot("CPU",50);Check(plot.Count<=200&&plot.Any(x=>x.Value==100),"downsample preserves peaks");log.Add("MISSING_INTERVALS_AND_FAILURES_NOT_INTERPOLATED=True");log.Add("DOWNSAMPLING_PRESERVES_PEAKS=True");
 string csv=Path.Combine(directory,"range.csv"),portable=Path.Combine(directory,"range.aqhistory");store.ExportCsv(recovered,csv);store.ExportArchive(recovered,portable,CancellationToken.None);var imported=store.Query(server,from,to,CancellationToken.None,portable);Check(imported.Points.Count==181&&store.Read(imported.Points[0]).Metrics().Processes[0].User=="baiyang","portable archive reopen");Check(File.ReadAllLines(csv).Length==182,"CSV sample count");Check(store.ReadHeader(portable).Start==from.Ticks,"portable interval");log.Add("CSV_EXPORT_AND_PORTABLE_REOPEN=True");
 var cleanup=new ArchiveStore(Path.Combine(directory,"retention")){Days=2,LimitMB=1};var folder=cleanup.Folder(server);Directory.CreateDirectory(folder);string expired=Path.Combine(folder,DateTime.UtcNow.AddDays(-4).ToString("yyyyMMdd-HH")+"-000.aqlog");File.WriteAllText(expired,"old");cleanup.Cleanup();Check(!File.Exists(expired),"age retention");string oldest=null;for(int i=0;i<4;i++){string file=Path.Combine(folder,DateTime.UtcNow.AddHours(-5+i).ToString("yyyyMMdd-HH")+"-000.aqlog");File.WriteAllBytes(file,new byte[400000]);if(i==0)oldest=file;}cleanup.Cleanup();Check(!File.Exists(oldest)&&cleanup.Info(server).Bytes<=1048576,"capacity retention");log.Add("AGE_AND_SIZE_RETENTION=True");
 var service=new ArchiveService(365,1024,Path.Combine(directory,"queue"));for(int i=0;i<20;i++)service.Enqueue(server,Sample(i),2);Check(service.Flush(10000),"writer flush");service.Dispose();Check(service.Store.Query(server,now.AddMinutes(-1),DateTime.UtcNow.AddMinutes(1),CancellationToken.None).Points.Count==20,"background durable writer");log.Add("BACKGROUND_WRITE_FLUSH_AND_SHUTDOWN=True");
 var window=new MonitorWindow(true,store);window.SetMetrics(Sample(45));window.SwitchView("历史");window.ArchiveView.SetRange(from,to,false);window.ArchiveView.QueryNow();Pump(()=>!window.ArchiveView.Loading);Check(window.ArchiveView.CurrentResult.Points.Count==181,"actual history query UI count="+(window.ArchiveView.CurrentResult==null?-1:window.ArchiveView.CurrentResult.Points.Count)+" status="+window.ArchiveView.StatusText);window.ArchiveView.SelectTime(from.AddMinutes(2).Ticks);Check(window.ArchiveView.SelectedPoint.T==from.AddMinutes(2).Ticks,"timeline nearest record");window.ArchiveView.SetMetric("GPU 0");Check(window.ArchiveView.Chart.Data.Count>0&&window.ArchiveView.Chart.Data.All(x=>x.Value==100),"individual GPU historical trend");window.ArchiveView.SetMetric("CPU");var slider=(Slider)typeof(ArchivePanel).GetField("timeline",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(window.ArchiveView);slider.Value=250;Check(Math.Abs(window.ArchiveView.SelectedPoint.T-(from.Ticks+(long)((to.Ticks-from.Ticks)*.25)))<TimeSpan.FromSeconds(11).Ticks,"time slider binding selects matching sample");log.Add("ASYNC_RANGE_QUERY_TIMELINE_AND_PER_GPU_HISTORY=True");log.Add("SLIDER_VALUE_TO_ARCHIVED_SNAPSHOT_BINDING=True");
 int renders=0;foreach(string theme in Theme.Keys){window.ApplyAppearance(theme);window.SwitchView("历史");window.ArchiveView.SetRange(from,to,false);window.ArchiveView.SetResult(recovered);Check(window.ArchiveView.DeviceBytes>0,"history archive status bytes key="+window.ArchiveView.DeviceKey+" expected="+ArchiveStore.Key(server));window.ArchiveView.ShowRecord(snapshot);foreach(int[] size in new[]{new[]{760,560},new[]{1200,1040}})foreach(int dpi in new[]{96,120,192}){window.RenderImage(Path.Combine(directory,theme+"-history-"+size[0]+"-"+dpi+".png"),size[0],size[1],dpi);Check(window.Audit().Count==0,"history layout");renders++;}}
 log.Add("HISTORY_THEME_SIZE_DPI_RENDERS="+renders);window.ChooseServer(other);Check(window.ArchiveView.CurrentResult==null,"changing device invalidates history");window.ArchiveView.SetRange(from,to,true);Pump(()=>!window.ArchiveView.Loading);Check(window.ArchiveView.CurrentResult.Points.Count==1,"no stale other device query");log.Add("HISTORY_DEVICE_SWITCH_INVALIDATES_STALE_RESULTS=True");window.SwitchView("GPU");window.RenderImage(Path.Combine(directory,"process-users-synthetic.png"),1100,850,120);window.Exit();
 var options=new Settings{RetentionDays=7,ArchiveLimitMB=256};options.Servers.Add(server);options.Servers.Add(local);Storage.PathName=Path.Combine(directory,"settings.xml");Storage.Save(options);var roundtrip=Storage.Load();Check(roundtrip.RetentionDays==7&&roundtrip.ArchiveLimitMB==256&&roundtrip.Servers.Count(x=>x.IsLocal)==1,"settings retain local and archive options");log.Add("LOCAL_AND_RETENTION_SETTINGS_ROUNDTRIP=True");File.WriteAllLines(Path.Combine(directory,"v5-results.txt"),log);Console.WriteLine(string.Join("\n",log));return 0;}
 public static void Runtime(Application app,string directory){directory=Path.GetFullPath(directory);Directory.CreateDirectory(directory);Storage.PathName=Path.Combine(directory,"runtime-settings.xml");ArchiveStore.DefaultRoot=Path.Combine(directory,"runtime-archives");var options=new Settings{Interval=2,SelectedName="aq-server"};var server=Storage.DefaultServer();var local=Storage.LocalServer();options.Servers.Add(server);options.Servers.Add(local);Storage.Save(options);var window=new MonitorWindow(false);app.MainWindow=window;window.Show();var start=DateTime.UtcNow.AddSeconds(-1);var watch=Stopwatch.StartNew();int stage=0;var log=new List<string>();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(500)};timer.Tick+=(a,b)=>{try{if(watch.Elapsed.TotalSeconds>55)throw new Exception("runtime polling timeout stage="+stage);var remote=window.ArchiveRepository.Query(server,start,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);var localData=window.ArchiveRepository.Query(local,start,DateTime.UtcNow.AddSeconds(1),CancellationToken.None);if(stage==0&&remote.Points.Count(x=>string.IsNullOrEmpty(x.Error))>=2){log.Add("RUNTIME_REMOTE_AUTO_ARCHIVE="+remote.Points.Count);window.ChooseServer(local);stage=1;}else if(stage==1&&localData.Points.Count(x=>string.IsNullOrEmpty(x.Error))>=2){log.Add("RUNTIME_LOCAL_AUTO_ARCHIVE="+localData.Points.Count);window.SwitchView("历史");window.ArchiveView.SetRange(start,DateTime.UtcNow.AddSeconds(1),true);stage=2;}else if(stage==2&&!window.ArchiveView.Loading){Check(window.ArchiveView.CurrentResult!=null&&window.ArchiveView.CurrentResult.Points.Count>=2,"runtime history UI results");log.Add("RUNTIME_HISTORY_QUERY=True");log.Add(window.NativeReview());bool tray=window.TrayVisible;bool close=window.SmokeCloseToTray();window.Restore();window.HideToTray();bool hidden=!window.IsVisible;window.Restore();log.Add("TRAY_CREATED="+tray);log.Add("CLOSE_TO_TRAY="+close);log.Add("HIDE_AND_RESTORE="+(hidden&&window.IsVisible));log.Add("STARTUP_NOT_MODIFIED=True");Check(tray&&close&&hidden&&window.IsVisible,"runtime tray lifecycle");window.RenderImage(Path.Combine(directory,"runtime-local-history.png"),1200,1040,120);timer.Stop();window.Exit();var final=new ArchiveStore(ArchiveStore.DefaultRoot);Check(final.Query(local,start,DateTime.UtcNow.AddSeconds(1),CancellationToken.None).Points.Count>=2,"flush on real application exit");var loaded=Storage.Load();Check(loaded.SelectedName==local.Name&&loaded.Servers.Any(x=>x.IsLocal),"last device and local config persisted");log.Add("EXIT_FLUSH_AND_LAST_DEVICE_PERSISTED=True");File.WriteAllLines(Path.Combine(directory,"runtime-results.txt"),log);}}
 catch(Exception error){timer.Stop();File.WriteAllText(Path.Combine(directory,"runtime-error.txt"),error.ToString());window.Exit();}};timer.Start();}
 public static int Live(string directory){directory=Path.GetFullPath(directory);Directory.CreateDirectory(directory);var store=new ArchiveStore(Path.Combine(directory,"live-store"));var server=Storage.DefaultServer();var local=Storage.LocalServer();var begin=DateTime.UtcNow.AddSeconds(-1);var log=new List<string>();Metrics remote=null,localMetrics=null;for(int i=0;i<3;i++){remote=Remote.Collect(server);Check(string.IsNullOrEmpty(remote.Error),"server: "+remote.Error);Check(remote.CpuCores.Count>100&&remote.Gpus.Count==8,"actual remote hardware");Check(remote.Raw.Contains("AQUSERS")&&System.Text.RegularExpressions.Regex.IsMatch(remote.Raw,@"(?m)^\s*\d+\s+baiyang\s*$"),"live Linux PID to username lookup");store.Append(server,ArchiveRecord.From(remote,DateTime.UtcNow,5));localMetrics=Remote.Collect(local);Check(string.IsNullOrEmpty(localMetrics.Error),"local: "+localMetrics.Error);Check(localMetrics.CpuCores.Count>0,"actual local cores");store.Append(local,ArchiveRecord.From(localMetrics,DateTime.UtcNow,5));log.Add("REMOTE_CORES="+remote.CpuCores.Count+" REMOTE_GPUS="+remote.Gpus.Count+" OWNERS="+string.Join(";",remote.Processes.Select(x=>x.Pid+":"+x.User))+" LOCAL_CORES="+localMetrics.CpuCores.Count+" LOCAL_GPU="+localMetrics.Gpus.Count);}
 var finish=DateTime.UtcNow.AddSeconds(1);var source=new ArchiveStore(store.Root);var queried=source.Query(server,begin,finish,CancellationToken.None);Check(queried.Points.Count==3,"live disk recovery");var window=new MonitorWindow(true,source);window.SetMetrics(remote);window.SwitchView("GPU");window.RenderImage(Path.Combine(directory,"remote-gpu-live.png"),1200,1000,120);window.Scroll.ScrollToBottom();window.RenderImage(Path.Combine(directory,"remote-processes-live.png"),1200,1000,120);window.SwitchView("历史");window.ArchiveView.SetRange(begin,finish,false);window.ArchiveView.SetResult(queried);window.ArchiveView.ShowRecord(source.Read(queried.Points.Last()));window.RenderImage(Path.Combine(directory,"remote-history-live.png"),1200,1040,120);window.Scroll.ScrollToBottom();window.RenderImage(Path.Combine(directory,"remote-history-snapshot-live.png"),1200,1000,120);window.ChooseServer(local);window.SetMetrics(localMetrics);window.SwitchView("CPU");window.RenderImage(Path.Combine(directory,"local-cpu-live.png"),1100,850,120);window.ShowCores();window.RenderImage(Path.Combine(directory,"local-cores-live.png"),1100,850,120);window.SwitchView("历史");var localResult=source.Query(local,begin,finish,CancellationToken.None);Check(localResult.Points.Count==3,"local disk recovery");window.ArchiveView.SetRange(begin,finish,false);window.ArchiveView.SetResult(localResult);window.RenderImage(Path.Combine(directory,"local-history-live.png"),1200,1040,120);source.ExportArchive(queried,Path.Combine(directory,"remote-live.aqhistory"),CancellationToken.None);window.Exit();log.Add("LIVE_ARCHIVE_REOPEN_REMOTE=3");log.Add("LIVE_ARCHIVE_REOPEN_LOCAL=3");File.WriteAllLines(Path.Combine(directory,"live-results.txt"),log);Console.WriteLine(string.Join("\n",log));return 0;}
}
